SELECT t.reference,t.statut,t.nb_colis,t.nb_cartons, count(DISTINCT c.commande_id) AS commandes, count(DISTINCT c.colis_id) AS cartons, (SELECT count(*) FROM public.livsuivi_commandes ls WHERE ls.tournee_id=t.tournee_id) AS suivis FROM public.tournees t LEFT JOIN public.colis c ON c.tournee_id=t.tournee_id WHERE t.reference='TRN-20260719-2394' GROUP BY t.tournee_id,t.reference,t.statut,t.nb_colis,t.nb_cartons;